import{_ as i,o as t,c as l,j as e,a as r,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/grundlagen/startbildschirm.png",u="/bilder/grundlagen/svws-server-landing-page.png",f=JSON.parse('{"title":"SchILD-NRW 3 kennenlernen","description":"","frontmatter":{"title":"SchILD-NRW 3 kennenlernen","source_pageid":1263,"source_revision":6968},"headers":[],"relativePath":"einstieg/grundlagen/uebersicht-schild-nrw-3-einfuehrung.md","filePath":"einstieg/grundlagen/uebersicht-schild-nrw-3-einfuehrung.md"}'),d={name:"einstieg/grundlagen/uebersicht-schild-nrw-3-einfuehrung.md"};function h(o,n,c,g,S,m){return t(),l("div",null,[...n[0]||(n[0]=[e("h1",{id:"schild-nrw-3-kennenlernen",tabindex:"-1"},[r("SchILD-NRW 3 kennenlernen "),e("a",{class:"header-anchor",href:"#schild-nrw-3-kennenlernen","aria-label":'Permalink to "SchILD-NRW 3 kennenlernen"'},"​")],-1),e("p",null,"Verschaffen Sie sich einen Überblick über die Aufgaben von SchILD-NRW 3 und sein Zusammenspiel mit dem SVWS-Server. Der Server muss vor dem Windows-Programm bereitstehen.",-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),r("Wichtig")]),e("p",null,[e("strong",null,"SchILD-NRW 3 ist ohne den SVWS-Server nicht lauffähig!")]),e("p",null,"Der SVWS-Server ist Voraussetzung für den Start von SchILD-NRW 3! Sie müssen daher:"),e("ol",null,[e("li",null,"Installieren Sie zuerst den SVWS-Server. Dabei werden der SVWS-Webclient und der SVWS-AdminClient mitinstalliert."),e("li",null,"Installieren Sie anschließend SchILD-NRW 3.")]),e("p",null,"Bei späteren Updates ist sowohl beim SVWS-Server als auch bei SchILD-NRW-3 auf neue Versionen zu prüfen!")],-1),s('<p><a href="/bilder/grundlagen/startbildschirm.png"><img src="'+a+'" alt="SchILD Startbildschirm.png" loading="lazy"></a></p><p>SchILD-NRW 3 ist das zentrale <strong>Sch</strong>ulverwaltungsprogramm für die <strong>I</strong>ndividualdaten- und <strong>L</strong>eistungs<strong>d</strong>atenverwaltung.</p><p>SchILD-NRW 3 verwendet ein Datenbanksystem, das viele gleichzeitige Benutzer und große Datenbestände unterstützt. Sie können es auf einem einzelnen Rechner oder in einer Netzwerkumgebung mit einem Server betreiben.</p><p>Das Windows-Programm verwaltet Schülerinnen und Schüler, Lehrkräfte, Erzieherinnen und Erzieher und Betriebe und ist für alle Schulformen in NRW geeignet.</p><p>Beziehen Sie <a href="https://svws.nrw.de" target="_blank" rel="noreferrer">SchILD-NRW 3</a> kostenfrei über die Webseite des MSB für Schulverwaltungssoftware.</p><h2 id="ausgewahlte-features-zur-ubersicht" tabindex="-1">Ausgewählte Features zur Übersicht <a class="header-anchor" href="#ausgewahlte-features-zur-ubersicht" aria-label="Permalink to &quot;Ausgewählte Features zur Übersicht&quot;">​</a></h2><ul><li>Verwalten Sie alle Leistungsdaten Ihrer Schülerschaft. Dies betrifft Noten, Teilleistungen, Quartalsnoten, Fehlzeiten usw.</li><li>Organisieren Sie den konfigurierbaren Unterricht in frei einstellbaren Klassen und Kursen von der Grundschule bis zu Abitur und Berufs- und Weiterbildungskolleg.</li><li>Verwalten Sie viele weitere Informationen Ihrer Schülerschaft, wie Adresse, unterschiedliche Erzieher, Fördermaßnahmen, KAoA, Buslinien, Sportbefreiungen, Einwilligen zu Lernplattformen und DSGVO-Einwilligungen.</li><li>Legen Sie weitere frei konfigurierte Vermerke an.</li><li>Filtern Sie Schüler nach allen in der Datenbank eingetragenen und frei kombinierbaren Kriterien.</li><li>Führen Sie automatische Abschluss- und Versetzungsberechnungen durch.</li><li>Führen Sie Änderungen über große Schülergruppen zeitsparend mit Gruppenprozessen aus.</li><li>Verwalten Sie Schülerfotos und Nummer für Schüler- und Lehrerausweise.</li><li>Verwalten Sie alle Personen und Kontakte in und um Ihre Schule aller Schulformen in NRW.</li><li>Verwalten Sie alle personen- und zeitabhängigen Daten Ihrer Lehrkräfte.</li><li>Bereiten Sie die amtliche Schulstatistik mit Hilfe von SchILD-NRW 3 vor.</li><li>Sichern Sie Ihre Datenbank von SchILD-NRW 3 aus.</li><li>Erzeugen Sie Noten-, Text- und Ankreuzzeugnisse und verwenden Sie hierzu konfigurierte Floskeln und zum Download bereitgestellte offizielle Zeugnisformulare.</li><li>Drucken Sie die Daten aus der Datenbank durch einen flexiblen Report-Designer als Übersichten, Listen, Schülerausweise, Stammblätter, Leistungsübersichten usw. aus. Nutzen Sie hier auch die zahlreichen mitgelieferten Vorlagen.</li><li>Archivieren Sie wichtige Schreiben als PDF direkt in eine schülerbezogene Dokumentenverwaltung oder Zeugnisse in ein Zeugnisverzeichnis.</li><li>Prüfen Sie automatisch die Daten auf eventuell geltende Löschfristen.</li><li>Erstellen Sie Serienbriefe und E-Mails direkt aus SchILD-NRW 3.</li><li>Nutzen Sie umfangreiche Möglichkeiten zum Im- und Export und die Schnittstelle von Textdateien von SchILD-NRW 3.</li><li>Nutzen Sie das vielfältige Supportangebot über die Webseite des MSB für Schulverwaltungssoftware und die Fortbildungsangebote Ihrer Bezirksregierung.</li></ul><h2 id="zusammenspiel-mit-dem-svws-server" tabindex="-1">Zusammenspiel mit dem SVWS-Server <a class="header-anchor" href="#zusammenspiel-mit-dem-svws-server" aria-label="Permalink to &quot;Zusammenspiel mit dem SVWS-Server&quot;">​</a></h2><p><a href="/bilder/grundlagen/svws-server-landing-page.png"><img src="'+u+'" alt="Übersicht der Infrastruktur zur Schulverwaltungssoftware. SchILD-NRW 3 benötigt den zuvor installierten SVWS-Server. Dieser bringt den über den Browser zu verwendenden SVWS-WebClient mit." loading="lazy"></a></p><p><em>Übersicht der Infrastruktur zur Schulverwaltungssoftware. SchILD-NRW 3 benötigt den zuvor installierten SVWS-Server. Dieser bringt den über den Browser zu verwendenden SVWS-WebClient mit.</em></p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=%C3%9Cbersicht:_SchILD-NRW_3_(Einf%C3%BChrung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6968.</p>',12)])])}const p=i(d,[["render",h]]);export{f as __pageData,p as default};
